167	export function renderServiceCard(service) {
168	    const currentLang = localStorage.getItem('app_lang') || 'ru';
169	
170	    const orderBtnText = {
171	        ru: 'Заказать',
172	        en: 'Order',
173	        fr: 'Commander',
