175	        es: 'Pedir',
176	        de: 'Bestellen',
177	        nl: 'Bestellen'
178	    };
179	    const btnText = orderBtnText[currentLang] || orderBtnText.ru;
180	
181	    const card = document.createElement('div');
182	    card.className = 'service-card';
183	    
184	    const badge = getCategoryBadge(service.category);
185	    const icon = getIconForService(service.category);
186	
187	    card.innerHTML = `
188	        <div class="card-header">
189	            <span class="service-icon">${icon}</span>
190	            <span class="badge ${badge.class}">${badge.label}</span>
191	        </div>
192	        <h3 class="service-title">${service.title}</h3>
193	        <p class="service-desc">${service.description}</p>
194	        <div class="card-footer">
195	            <span class="service-price">${service.price}</span>
196	            <a href="#/contacts" class="btn-card">${btnText}</a>
197	        </div>
198	    `;
199	    return card;
200	}

